CREATE TABLE nodi_rete (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    tipo TEXT NOT NULL CHECK (tipo IN ('router', 'switch', 'server', 'firewall')),
    parent_id INT REFERENCES nodi_rete(id),
    data_installazione DATE CHECK (data_installazione <= CURRENT_DATE)
);

CREATE INDEX idx_nodi_rete_parent_id ON nodi_rete(parent_id);
